<template>
  <div class="video-style-transfer-panel">
    <!-- 标题区域 -->
    <div class="panel-header">
      <h3 class="panel-title">{{ t('changeVideoStyle') }}</h3>
      <p class="panel-subtitle">{{ t('selectStyle') }}</p>
    </div>

    <!-- 视频上传/预览区域 -->
    <div class="video-upload-container">
      <div class="video-wrapper">
        <upload-video
          width="100%"
          height="260px"
          :max-size="100"
          :default-url="formData.uploadedVideoUrl"
          :default-poster="formData.uploadedPosterUrl"
          @upload-success="handleVideoUploadSuccess"
          @delete-success="handleVideoDeleteSuccess"
          @upload-error="handleVideoUploadError"
        />
      </div>
    </div>

    <!-- 风格选择区域 -->
    <div class="style-selection-section">
      <div class="section-title">{{ t('selectVideoStyle') }}</div>
      
      <!-- 风格选项 -->
      <div class="style-options">
        <div 
          v-for="style in styleOptionsRef" 
          :key="style.value"
          class="style-option"
          :class="{ active: formData.selectedStyle === style.value }"
          @click="selectStyle(style.value)"
        >
          {{ style.label }}
        </div>
      </div>
    </div>

    <!-- 生成按钮 -->
    <div class="generate-section">
      <el-button
        block
        class="generate-button"
        :disabled="isDisabledButton"
        :class="{ disabled: isDisabledButton }"
        :loading="isGenerating.value"
        @click="handleGenerate"
      >
        <l-img w="18px" h="18px" src="/static/images/video-icon.png" />
        {{ t('generateVideo') }}
      </el-button>
    </div>
  </div>
</template>

<script setup>
// 引入区域
import { ref, reactive, onMounted, onBeforeUnmount, onUnmounted ,computed} from 'vue';
import { ElMessage } from 'element-plus';
import { useI18n } from 'vue-i18n';
import LImg from '@/components/l-img.vue';
import UploadVideo from '@/components/upload/video.vue';
import { useMediaGenerationStore } from '@/store/modules/media-generation';
import { styleOptions } from '@/types/panel-options';
import { addTaskToPolling, TaskType } from '@/presenter/media-task-polling';
import { mediaTaskEventBus, clearMediaTaskEventListeners } from '@/presenter/media-task-events';
import router from '@/router';
import { VIDEO_OPERATIONS } from '@/types/media-tool';

// 变量区域
const { t } = useI18n();
const mediaStore = useMediaGenerationStore();


// 当前模块的 key
const MODULE_KEY = VIDEO_OPERATIONS.VIDEO_STYLE;

// 表单数据统一管理
const formData = reactive({
  // 上传视频相关
  uploadedVideoUrl: '',
  uploadedPosterUrl: '',
  uploadedVideoInfo: null,
  
  // 风格选择
  selectedStyle: '',
  
});

const isGenerating = ref(false);
// 当前任务ID，用于事件过滤
const currentTaskId = ref(null);
// 风格选项
const styleOptionsRef = ref(styleOptions);

const isDisabledButton = computed(() => {
  return !formData.selectedStyle || formData.uploadedVideoUrl === '' || isGenerating.value;
});

// 获取存储的生成结果
const loadGenerationResult = () => {
  const result = mediaStore.getGenerationResult(MODULE_KEY);
  if (result) {
    // 设置默认视频URL和封面
    if (result.videoUrl) {
      formData.uploadedVideoUrl = result.videoUrl;
    }
    if (result.posterUrl) {
      formData.uploadedPosterUrl = result.posterUrl;
    }
  }
};

// 清除生成结果
const clearGenerationResult = () => {
  mediaStore.clearGenerationResult(MODULE_KEY);
};

// 点击事件区域
const selectStyle = (style) => {
  formData.selectedStyle = formData.selectedStyle === style ? '' : style;
};

// 监听事件区域
const handleVideoUploadSuccess = (videoInfo) => {
  formData.uploadedVideoInfo = videoInfo;
  formData.uploadedVideoUrl = videoInfo.url;
  formData.uploadedPosterUrl = videoInfo.posterUrl;
};

const handleVideoDeleteSuccess = () => {
  formData.uploadedVideoInfo = null;
  formData.uploadedVideoUrl = '';
  formData.uploadedPosterUrl = '';
};

const handleVideoUploadError = (error) => {
  console.error('Video upload error:', error);
};

// 处理任务完成事件
const handleTaskCompleted = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    // 构造结果数据
    const result = {
      id: Date.now(),
      selectedStyle: styleOptionsRef.value.find(s => s.value === formData.selectedStyle)?.label || formData.selectedStyle,
      originalVideo: formData.uploadedVideoInfo,
      uploadedVideoInfo: formData.uploadedVideoInfo,
      videoUrl: res.result?.media_list?.[0]?.file_url || formData.uploadedVideoUrl,
      posterUrl: formData.uploadedPosterUrl,
      enhancedVideo: res.result?.media_list?.[0]?.file_url || 'style-transfer-video.mp4',
      quality: 'HD',
      processingTime: Math.floor(Math.random() * 60) + 30,
      generatedAt: new Date().toISOString()
    };
    
    emit('generate-success', result);
    isGenerating.value = false;
    currentTaskId.value = null;
  }
};

// 处理任务失败事件
const handleTaskFailed = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    emit('generate-error', res);
    isGenerating.value = false;
    currentTaskId.value = null;
  }
};

// 处理任务状态更新事件
const handleTaskStatusUpdate = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    // 更新进度等信息
    console.log(`Video style transfer progress: ${res.res.progress}%`);
    emit('loading', true, res.res.estimated_time || null);
  }
};

// 业务逻辑区域


const emit = defineEmits(['generate-success', 'generate-error', 'generate-create', 'loading']);

const handleGenerate = async () => {
  if (!formData.selectedStyle) {
    ElMessage.warning(t('pleaseUploadVideoAndSelectStyle'));
    return;
  }

  try {
    emit('generate-create');
    emit('loading', true, null);
    isGenerating.value = true;
    
    // 准备请求数据
    const requestData = {
      videoInfo: formData.uploadedVideoInfo,
      videoUrl: formData.uploadedVideoUrl,
      selectedStyle: formData.selectedStyle
    };

    console.log('Video style transfer with data:', requestData);
    
    // TODO: 调用真实的API (暂时忽略，接口不支持)
    // const result = await apiGeneration.videoStyleTransfer(requestData);
    
    // 模拟API响应
    const apiResult = {
      task_id: `task_video_style_${Date.now()}`,
      status: 'pending'
    };
    
    // 设置路由meta并添加到轮询管理器
    const meta = router.currentRoute.value.meta;
    meta.taskId = apiResult.task_id;
    meta.type = TaskType.VIDEO;
    addTaskToPolling(apiResult.task_id, TaskType.VIDEO);
    
    // 设置当前任务ID
    currentTaskId.value = apiResult.task_id;
    
  } catch (error) {
    emit('loading', false, null);
    isGenerating.value = false;
    emit('generate-error', error);
  }
};

// 重置表单数据
const resetFormData = () => {
  formData.uploadedVideoUrl = '';
  formData.uploadedPosterUrl = '';
  formData.uploadedVideoInfo = null;
  formData.selectedStyle = '';
};

// 获取表单数据（用于父组件获取）
const getFormData = () => {
  return {
    uploadedVideoUrl: formData.uploadedVideoUrl,
    uploadedPosterUrl: formData.uploadedPosterUrl,
    uploadedVideoInfo: formData.uploadedVideoInfo,
    selectedStyle: formData.selectedStyle,
  };
};

// 周期函数区域
onMounted(() => {
  // 获取之前保存的生成结果
  loadGenerationResult();
  
  // 绑定媒体任务事件监听器（只绑定一次）
  mediaTaskEventBus.on('task-completed', handleTaskCompleted);
  mediaTaskEventBus.on('task-failed', handleTaskFailed);
  mediaTaskEventBus.on('task-status-update', handleTaskStatusUpdate);
});

// 组件卸载前清理生成结果
onBeforeUnmount(() => {
  clearGenerationResult();
  // 清理事件监听器（只清理一次）
  clearMediaTaskEventListeners();
});

// 导出区域
defineExpose({
  resetFormData,
  getFormData
});
</script>

